exec(open("batches/hiv_common.py").read())
# HIV 2022 part 3, pp.190-198 (Chapter 8: postnatal retesting, mother-baby pair schedule, infant testing, HIV-exposed infant care,
# eIP special cases, infant feeding). From the page images; cell text from the PDF grid.
C8 = "Chapter 8: Prevention of Mother to Child Transmission of HIV"
AMD = "Check the 2024 Amendment (Chapter 8: PMTCT) for updated infant prophylaxis and infant testing guidance."
ITEMS = [
 T("tbl-8.11-retesting-lactating", 190, C8 + " > 8.7 Services for Lactating Women and their Children > Table 8.11", "Table 8.11 Retesting schedule for Lactating Women in Postnatal Care", ["0515"],
   [r("Population", "Retesting and prevention")], [r("HIV-negative Women", "• As part of efforts to achieve the elimination of mother-to-child transmission (eMTCT) of HIV and syphilis, all HIV-negative lactating women should be re-tested at 6 weeks, 14 weeks, 6 months, 9 months, 12 months, 15 months and 18 months aligned with the MBP schedule.<br/>• Emphasize primary prevention of HIV (see Table 8.2) which includes the provision of PrEP using the opt-out approach<br/>• HIV-negative lactating women on PrEP should be retested based on the PrEP retesting schedule which can be aligned with planned child welfare/MBP schedules.")],
   context_before="Caesarean section: a routine caesarean section is not recommended for PMTCT purposes. Newly diagnosed HIV-positive women must be initiated on ART at least 2 hours before an elective caesarean section for obstetric indications and continue ART post-operatively (even during the 'nil per os' period).",
   footnotes=["All lactating mothers who are HIV-negative should be re-tested every 2 months (aligned with the mother-baby postpartum care visits) until the end of breastfeeding."],
   source_flags=["Column headings added. Retesting frequency differs within the section: the table gives fixed points (6, 14 weeks, 6, 9, 12, 15, 18 months), the text below says every 2 months until the end of breastfeeding."]),
 T("fig-8.2-mbp-schedule", 190, C8 + " > 8.7 > Follow-Up of Mother-Baby Pairs After Delivery > Figure 8.2", "Figure 8.2 Mother and Baby Appointment Schedule during Postpartum Care (post-natal care using the MBP model)", ["0517"],
   [r("Visit", "Mother ART refill and baby services")],
   [r("7-14 days", "✓"), r("6 weeks", "✓ Stop AZT; check VL"), r("10 weeks", "✓"), r("14 weeks", "✓ Decide on NVP"), r("6 months", "✓ Check VL"), r("9 months", "✓ DNA PCR"),
    r("12 months", "✓ DNA PCR"), r("15 months", "✓"), r("18 months", "✓ Rapid test baby. Plan next test if breastfeeding")],
   context_before="Mothers and their babies should be seen as a pair from delivery; mother-baby pair visits are aligned to the child immunization schedule and ART appointments for mother and baby are linked to them.",
   source_flags=["The text calls this schedule 'Figure 6.2' and then 'Figure 8.2'.", "The schedule has no birth-test or 6-8 week infant test entries (Table 8.13 tests at birth and 6-8 weeks)."]),
 D("fig-8.3-infant-testing-approach", 191, C8 + " > 8.8 Services for HIV Exposed Infants > 8.9 HIV testing approach for infants and children > Figure 8.3", "Figure 8.3 Comprehensive HIV testing approach for infants and children", [],
   "Four complementary approaches:\n- Infant diagnosis: infant diagnosis as a multi-step process; same-day testing and return of results; confirmatory testing of all HIV-positives as ART is initiated; final, end-of-exposure diagnosis with an age-appropriate test.\n"
   "- Facility-based testing: determine the exposure status of all infants and children attending malnutrition wards, TB wards and inpatient wards; in the absence of the mother, test the infant with an age-appropriate test.\n"
   "- Targeted testing: test known HIV-exposed infants and children whenever they present sick; offer to determine the exposure status of infants and children who present to outpatient and immunization clinics.\n"
   "- Index case and family testing: test infants and children living in the households of known HIV-positive parents or siblings.\n"
   "A lactating woman who acutely seroconverts and/or is believed to have recent HIV infection is at very high risk of transmitting HIV to the infant: consult the mother facility and/or Baylor for consideration of alternative EIP for the infant."),
 T("tbl-8.12-infant-tests-by-mother-status", 191, C8 + " > 8.10 Infant Diagnosis > Table 8.12", "Table 8.12 Infant Diagnostic Tests for Mothers of Varying HIV Statuses", ["0521"],
   [r("Mother Status", "Infant Diagnostic Tests")], [r(a, b) for a, b in [["Mother Known HIV-Positive", "• Nucleic acid tests-NAT (RNA and/or DNA PCR) for the child at birth (0-3days), 6-8 weeks, 9 months, and 12 months. The rapid test should be done at 18 months and if positive, should be confirmed with NAT before ART is initiated."], ["Mother HIV Status Unknown", "• Conduct HIV rapid test for mother.<br/>• If the mother is positive conduct NAT (RNA and/or DNA PCR) for the child immediately, then follow the EID schedule if the child tests negative. If the child is less than 6 weeks, start AZT/NVP EIP. If the child is older than 6 weeks, start NVP until a minimum of 14 weeks and/or the mother is undetectable<br/>• If the mother is negative, the child is not HIV-exposed. Repeat HIV rapid test for mother every 8 weeks until the end of breastfeeding. Provide PrEP to the mother using the Opt-Out approach."], ["Mother is not Available", "• NAT (RNA and/or DNA PCR) for the child immediately to ascertain HIV status, then follow the EID schedule if the child tests negative."]]],
   source_flags=["Mother HIV-negative: repeat her rapid test 'every 8 weeks until the end of breastfeeding' here vs fixed time points in Table 8.11.", "Final infant test 'at 18 months' only; WHO also requires a test 3 months after cessation of breastfeeding (Table 8.13 uses 2 months).", AMD]),
 T("tbl-8.13-infant-testing-timing", 192, C8 + " > 8.10 Infant Diagnosis > Table 8.13", "Table 8.13 Timing of HIV testing among exposed Infants and Young Children less than 18 months", ["0522", "0523", "0524", "0525", "0526", "0527"],
   [r("Age of Infant", "Eligible for Testing", "Which Test to Use", "Child status", "Management")],
   [[C("Birth (0-3 days)", rs=3), C("HIV-exposed infants (If exposure status is not known - test mother, if mother not available, test child using NAT)", rs=3), C("NAT (RNA and/or DNA PCR)", rs=3),
     C("HIV-negative, never breastfed"), C("Inform mother that child is HIV-negative; start eIP; check and enforce ART adherence for mother; test child again at 6-8 weeks.")],
    r("HIV-negative, breastfeeding", "Start eIP; check and enforce ART adherence for mother; re-test child at 6-8 weeks or 2 months after stopping breastfeeding or if they present with symptoms suggestive of HIV (whichever comes first)"),
    r("HIV-positive", "Take blood for confirmatory NAT test; initiate child on ART (do not await results of second NAT); check and enforce ART adherence for mother and baby"),
    [C("6-8 weeks", rs=3), C("HIV-exposed infants who tested HIV-negative at birth or missed birth testing (If exposure status is not known - test mother, if the mother is not available, test child using NAT)", rs=3), C("NAT (RNA and/or DNA PCR)", rs=3),
     C("HIV-negative, never breastfed"), C("Inform the mother that child is HIV-negative; continue eIP and stop at 14 weeks. Conduct an 18 months exit rapid test.")],
    r("HIV-negative, still breastfeeding", "Continue eIP; start Co-trimoxazole preventive therapy (CPT); check and enforce ART adherence for the mother; re-test the child at 9 months or 2 months after stopping breastfeeding or if they present with symptoms suggestive of HIV (whichever comes first)"),
    r("HIV-positive", "Stop eIP; take blood for confirmatory testing; initiate child on ART (do not await results of second NAT); start the child on Co-trimoxazole preventive therapy (CPT); check and enforce ART adherence for mother, continue breastfeeding. Breastfeeding is very important for an HIV-positive infant!"),
    [C("9 months", rs=4), C("HIV-exposed infants who tested HIV-negative at 6-8 weeks or missed 6-8 week test (if exposure status is not known - test mother, if the mother is not available, test child using NAT)", rs=4), C("NAT (RNA and/or DNA PCR)", rs=4),
     C("HIV-negative, never breastfed or stopped breastfeeding at least 2 months before the current test"), C("Inform the mother that child is HIV-negative; check and enforce ART adherence for the mother; conduct an exit rapid test at 18 months")],
    r("HIV-negative, stopped breastfeeding within 2 months of the current test", "Check and enforce ART adherence for the mother; re-test the child 2 months after cessation of breastfeeding (if positive - take blood for confirmatory testing and initiate ART; if negative - inform the mother that child is HIV-negative)"),
    r("HIV-negative, still breastfeeding", "Check and enforce ART adherence for mother; assure recent VL and re-test child at 12 months or 2 months after stopping breastfeeding or if they present with symptoms suggestive of HIV (whichever comes first)"),
    r("HIV-positive", "Take blood for confirmatory testing; initiate child on ART (do not await results of second NAT); start the child on CTX; check and enforce ART adherence for mother, continue breastfeeding"),
    r("12 months", "HIV-exposed infants who tested HIV-negative at 9 months or missed test at 9 months (If exposure status is not known - test mother, if the mother is not available, test child using NAT)", "NAT (RNA and/or DNA PCR)", "All results",
      "Manage as above, however, if the child tests HIV-negative and is still breastfeeding re-testing should be done at 18 months or 2 months after stopping breastfeeding or if they present with symptoms suggestive of HIV (whichever comes first)"),
    r("18 months", "HIV-exposed infants who tested HIV-negative at 12 months or missed the 12 months test (If exposure status not known - test mother, if mother not available, test child using Antibody test)", "HIV Antibody Test (follow national algorithm)", "All results",
      "Manage as above, however; if child tests HIV-positive, re-testing before ART initiation should be done using an antibody test instead of DNA PCR. If the child tests HIV-negative and is still breastfeeding re-testing should be done 2 months after stopping breastfeeding or if they present with symptoms suggestive of HIV (whichever comes first)")],
   rhc=1, pages=[192, 193],
   source_flags=["The PDF shows the child status as a colour key (green: HIV-negative, never breastfed; amber: HIV-negative, still breastfeeding; red: HIV-positive); written out here as a column.",
                 "Re-test '2 months after stopping breastfeeding' and 'whichever comes first' differ from WHO (final test at 18 months or 3 months after cessation of breastfeeding, whichever is later); see also the flag on Figure 3.8.",
                 "Never-breastfed infants: eIP is 'stop at 14 weeks' here, while Table 8.16 gives AZT and NVP for 6 weeks only for infants on replacement feeding.", AMD]),
 T("tbl-8.14-exposed-infant-package", 194, C8 + " > 8.10 Infant Diagnosis > Table 8.14", "Table 8.14 Package of care for HIV-Exposed Infants", ["0528", "0529", "0530", "0531"],
   [r("Service", "Description")], [r(a, b) for a, b in [["Early infant diagnosis and treatment Point-of-care testing is preferred due to its short turnaround time", "• See Table 8.13 for HIV testing in infants and young children.<br/>• All HIV-exposed infants should be re-tested 2 months after cessation of breastfeeding.<br/>• Children presenting with symptoms suggestive of HIV infection should be tested at any point of contact.<br/>• Infants at high risk of infection (e.g., mothers with high viral load or seroconverted) can be tested outside of the routine time points to assure that they are diagnosed positive as quickly as possible.<br/>• Immediately initiate all HIV-positive infants for ART:<br/>» A second HIV test should be conducted for all infected children before ART initiation (do not wait for results of the second test before initiating ART). » Refer to Chapter 9 section 9.5 for details on ART for children."], ["Growth and developmental assessment and immunization", "• Follow the EPI assessment and immunisation schedule"], ["Enhanced infant prophylaxis (eIP)", "• See Section 8.11"], ["Vigilance for HIV infection and re-testing", "• Maintain a high level of suspicion for HIV infection. Watch for:<br/>• Growth failure (i.e., a child falling off the growth curve).<br/>• Poor development (i.e., delays in achieving or loss of developmental milestones).<br/>• Clinical signs or symptoms are suggestive of HIV infection. If HIV is suspected, the child should be re-tested, staged both clinically and immunologically, and presumptively enrolled in HIV care and treatment."], ["Cotrimoxazole preventive therapy (CPT)", "• Give CPT to all HIV-exposed infants, starting from 6 weeks of age, to prevent PJP and other potentially fatal infections (see Chapter 9, section 9.7).<br/>• Continue treatment until HIV infection has been definitively ruled out AND the infant is no longer breastfeeding.<br/>• CPT is generally well tolerated by infants. However, parents should be counselled that if the child develops a severe rash (that includes sores in the mouth and red eyes), they should bring the child to the nearest health facility for evaluation.<br/>• In the rare circumstance that a child has a history of a severe (Grade IV) adverse reaction to CPT or other sulpha-containing drugs or known severe kidney disease (creatinine >3 times normal) and/or hepatic disease (liver function tests >5 normal), CPT should be avoided. Dapsone at a dose of 2 mg/kg once daily can be given as an alternative in these circumstances."], ["TB Preventive therapy for children with known TB contacts", "• HIV-exposed infants who live with someone with active TB are at risk of TB infection. Please refer to Chapter 9, Section 9.7 for more information.<br/>• Investigate for TB and if TB is excluded, give TB preventive therapy (TPT) for 6 months at a dose of 10 mg/kg.<br/>• Pyridoxine (1–2 mg/kg) should be given to prevent side effects of isoniazid (INH).<br/>• See TB program guidelines for more details about TPT and dosing.<br/>• Children receiving TPT should be monitored closely for the development of active TB."], ["Early treatment of infections", "• Be actively alert for infections and treat them early by following the guidelines for the integrated management of childhood illnesses (IMCI)."], ["Infant feeding and nutrition counselling", "• See section 8.12 on infant and young child feeding recommendations."], ["Maternal and family health and well-being", "• Assess the health and psychosocial well-being of family members and/or caregivers. The health of HIV-exposed infants is directly tied to the health of their caregivers.<br/>• At each visit, refer the child’s mother for CD4 count, ART initiation if eligible and family planning. Ask all caregivers about TB symptoms.<br/>• Offer HTS for any family members who have not been tested.<br/>• Provide psychosocial support to the family."], ["Early infant male circumcision (EIMC) counselling", "• Counsel parents on the importance of EIMC for their infant and refer infant for EIMC at facilities where services are available."]]], pages=[194, 195],
   footnotes=["Steps to successful early infant diagnosis and treatment: 1. Record contact information of mother (cell phone or physical/residential address). 2. Reinforce the importance of returning for test results. 3. Encourage woman to bring partner to discuss test results. 4. Emphasize that for all HIV-positive children, ART will be initiated urgently to keep the child alive and healthy. 5. Ensure that counselling and support are available to the family."]),
 T("tbl-8.15-eip-special-cases", 196, C8 + " > 8.11 Enhanced Infant Prophylaxis (eIP) > Table 8.15", "Table 8.15 Special Considerations for Enhanced Infant Prophylaxis in Exposed Infants", ["0534"],
   [r("Situation", "Action (*provide dosing clips and syringe)")], [r(a, b) for a, b in [["Mother diagnosed as HIV- positive during breastfeeding (acute seroconversion)", "• The infant is at extreme risk of HIV transmission. Consult MD, mother facility, or Baylor for considerations of presumptive ART for the infant. Lacking specific same-day advice, test infant same day and start routine EIP. If < 6 weeks, start AZT/NVP. If > 14 weeks, start only NVP.<br/>• Start ART on the mother immediately.<br/>• Test infant on the same day"], ["Mother diagnosed as HIV- positive during breastfeeding and refuses to be initiated on ART", "• The infant is at extreme risk of HIV transmission. Consult MD, mother facility or Baylor for considerations of presumptive ART for the infant. Lacking specific same-day advice, test infant same day and start routine EIP. If < 6 weeks start AZT/NVP. If > 14 weeks, start only NVP.<br/>• Test the infant on the same day.<br/>• Continue counselling the mother on the benefits of ART for her health, the baby’s and partner’s health"], ["The child defaulted from eIP before they are 14 weeks old", "• Counsel on the importance of ongoing prophylaxis and restart AZT up until 6 weeks postpartum and NVP until 14 weeks of age or until the mother has undetectable VL"], ["Mother is on 2nd or 3rd line", "• Consult Baylor for guidance on appropriate Infant Prophylaxis. If lacking specific guidance start routine EIP with AZT/NVP"]]],
   context_before="All HIV-exposed infants should be given eIP (NVP and AZT syrup) from the time of birth. The duration of AZT is 6 weeks post-partum. The minimum duration of NVP is 14 weeks post-delivery; NVP should be continued beyond 14 weeks if the mother is breastfeeding and has a detectable viral load, and only stopped once the mother is undetectable. Prompt consultation is advised for women viraemic on 2nd or 3rd line ART while pregnant or breastfeeding.",
   footnotes=["Note: Give AZT only up until 6 weeks post-partum regardless of the start date. Give NVP until at least 14 weeks of age but may continue for longer until the mother has a detectable VL."],
   source_flags=["The note says NVP 'may continue for longer until the mother has a detectable VL'; it should read until the mother has an UNDETECTABLE VL (section 8.11 and Table 8.9).",
                 "Acute seroconversion: 'If < 6 weeks, start AZT/NVP. If > 14 weeks, start only NVP' leaves infants aged 6-14 weeks without guidance.", AMD]),
 T("tbl-8.16-infant-feeding", 197, C8 + " > 8.12 Infant and Young Child Feeding Recommendations > Table 8.16", "Table 8.16 Recommendations for Infant and Young Child Feeding Based on HIV Status of Mother", ["0537", "0538", "0539"],
   [r("Situation", "Recommendations")], [r(a, b) for a, b in [["Mother is known to be HIV-negative or whose HIV status is unknown", "• Exclusive breastfeeding for the first 6 months with the addition of complementary feeding thereafter while breastfeeding continues for 24 months or beyond<br/>• HIV Testing should be offered for HIV-negative women and those of unknown status together with their partners at every PNC visit until the cessation of breastfeeding<br/>• Offer PrEP to all breastfeeding women at each visit."], ["Mother is known to be HIV-positive and on lifelong ART whose infant is HIV-negative or of unknown HIV status", "• Exclusive breastfeeding for the first 6 months with the addition of complementary feeding thereafter<br/>• Mothers living with HIV should breastfeed for at least 12 months and may continue breastfeeding for up to 24 months or beyond (similar to the general population) while being fully supported for ART adherence.<br/>• All HIV exposed infants who are breastfeeding should be provided with eIP<br/>• » AZT and NVP for 6 weeks. This should be dispensed in maternity (if not given during ANC)<br/>• » NVP only from 6 weeks to a minimum of 14 weeks. This should be dispensed during the 6-week PNC visit<br/>• The mother should continue with her ART for life"], ["Mother is known to be HIV-positive and whose infant is HIV-positive", "• Mothers should be encouraged to exclusively breastfeed for the first 6 months of life and continue breastfeeding for up to two years or beyond<br/>• Complementary feeding should be introduced from six months while breastfeeding continues<br/>• HIV-infected infants should be started on ART as soon as possible.<br/>• The mother should continue with her ART for life"], ["HIV-infected mothers who are well counselled but are considering not breastfeeding", "• Health care workers should conduct a one-on-one discussion/counselling session with each woman on how to feed their infants and consider her circumstances<br/>• Replacement feeding can be advised if the woman fulfils certain criteria. See the replacement feeding section below<br/>• All HIV-exposed infants on replacement feeding should receive AZT and NVP prophylaxis from birth up to 6 weeks<br/>• The mother should continue with her ART for life"], ["HIV-infected mothers who decide to stop breastfeeding", "• When mothers known to be living with HIV decide to stop breastfeeding at any time, infants should be provided with safe and adequate replacement feeds to enable normal growth and development.<br/>• See below (under replacement feeding) for alternatives to breastfeeding<br/>• Mothers known to be living with HIV who decide to stop breastfeeding at any time should stop gradually within one month.<br/>• Infants who have been receiving eIP should continue prophylaxis for two weeks after breastfeeding is fully stopped.<br/>• Stopping breastfeeding abruptly is not advisable.<br/>• Mother should continue with ART for life"]]],
   context_before="All mothers, including those living with HIV, should be counselled on the benefits of breastfeeding and encouraged and supported to exclusively breastfeed for the first 6 months, continue breastfeeding for at least 12 months and up to 24 months or beyond with complementary feeding after 6 months, while fully supported to adhere to care, maintain VL suppression and consistent condom use. Replacement feeding can be advised if the woman fulfils certain criteria (see Table 8.17; the text says 'Table 8.28').",
   source_flags=["Infants on replacement feeding: AZT and NVP 'from birth up to 6 weeks' here, but the replacement-feeding text (p.198) says continue NVP until 14 weeks."]),
 T("tbl-8.17-replacement-feeding", 198, C8 + " > 8.12 > Assessment for Replacement Feeding > Table 8.17", "Table 8.17 Assessment for replacement feeding", ["0542"],
   [r("#", "Assess the following conditions for safe formula feeding", "YES", "NO")],
   [r("1", "Are safe water and sanitation assured in the home and the community?", "", ""), r("2", "Can the mother afford and reliably provide sufficient infant formula milk to support the normal growth and development of the infant (about E500 per month)?", "", ""),
    r("3", "Can the mother/caregiver prepare formula milk cleanly and frequently enough so that it is safe and carries a low risk for diarrhoea and malnutrition?", "", ""), r("4", "Can the mother exclusively give infant formula?", "", ""),
    r("5", "Is the family supportive of exclusive replacement feeding?", "", ""), r("6", "Can the mother or caregiver access health care that offers comprehensive child health services?", "", ""),
    [C("• If YES to ALL, exclusive replacement feeding can be recommended.<br/>• If NO to ANY of the questions, recommend breastfeeding. Assure mother that ART and being undetectable makes breastfeeding safe", cs=4)]],
   rhc=2, context_before="Replacement feeding: a mother who opts for replacement feeding from birth should provide nutritionally adequate and safe replacement feeds and meet the conditions in Table 8.17. All HIV-exposed infants on replacement feeding should receive AZT and NVP prophylaxis from birth up to 6 weeks and then continue with NVP until 14 weeks (Table 8.10). Under 6 months: exclusive commercial infant formula if home conditions are fulfilled. Over 6 months: appropriate commercial infant formula, or full cream/whole/undiluted animal milk (boiled for infants less than 12 months) as part of a diet adequate in micronutrients, with meals 6 times per day; all children need complementary foods from 6 months.",
   footnotes=["Expressing breast milk is part of exclusive breastfeeding for mothers who cannot breastfeed on demand. Complementary feeding is essential from 6 months of age, while breastfeeding continues for 24 months or beyond; breast milk still provides about 50% of nutritional requirements between 6 and 12 months."]),
]
